<template>
  <div class="owner-page" :class="{ embedded }">
    <header v-if="!embedded" class="owner-header">
      <RouterLink class="brand" to="/home"><img src="/logo_transparent.png" alt="VibeLocate"><b>Vibe<span>Locate</span></b><em>AI</em></RouterLink>
      <nav><RouterLink to="/home">Home</RouterLink><RouterLink to="/home#featured">Buy</RouterLink><RouterLink to="/rent">Rent</RouterLink><RouterLink to="/map">Interactive Map</RouterLink><RouterLink to="/home#districts">Areas</RouterLink></nav>
      <div class="header-tools"><button><i class="fa-solid fa-globe"></i> AR | <b>EN</b></button><button class="round"><i class="fa-solid fa-moon"></i></button><button class="add-small" @click="router.push('/add-property')">List Your Property <i class="fa-solid fa-plus"></i></button><div class="mini-avatar"><img v-if="currentUser.avatar" :src="currentUser.avatar" :alt="currentUser.name"><span v-else>{{ initials }}</span></div></div>
    </header>

    <div class="owner-layout">
      <aside v-if="!embedded" class="sidebar">
        <div class="owner-profile"><div class="avatar"><img v-if="currentUser.avatar" :src="currentUser.avatar" :alt="currentUser.name"><span v-else>{{ initials }}</span></div><div><b>{{ currentUser.name }}</b><span>{{ currentUser.email }}</span><small><i class="fa-solid fa-circle-check"></i> Verified Member</small><button @click="router.push('/profile/edit')">Edit Profile <i class="fa-solid fa-arrow-right"></i></button></div></div>
        <div class="side-nav">
          <button @click="router.push('/profile')"><i class="fa-solid fa-table-cells-large"></i> Dashboard</button>
          <button class="active"><i class="fa-regular fa-building"></i> My Properties</button>
          <button @click="scrollToInquiries"><i class="fa-regular fa-message"></i> My Inquiries <b class="count">{{ inquiries.length }}</b></button>
          <button @click="router.push('/profile/saved')"><i class="fa-regular fa-heart"></i> Saved Properties</button>
          <button @click="router.push('/profile/alerts')"><i class="fa-solid fa-magnifying-glass"></i> My Searches</button>
          <button @click="router.push('/profile/settings')"><i class="fa-solid fa-gear"></i> Account Settings</button>
          <button @click="showToast('Subscription plans opened')"><i class="fa-solid fa-crown"></i> Subscription</button>
          <button @click="showToast('Support team is ready to help')"><i class="fa-regular fa-circle-question"></i> Help & Support</button>
          <button @click="logout"><i class="fa-solid fa-arrow-right-from-bracket"></i> Log Out</button>
        </div>
        <div class="upgrade-card"><i class="fa-solid fa-crown"></i><b>Upgrade Your Plan</b><p>Get more visibility, leads and premium features.</p><button @click="showToast('Plan options opened')">View Plans <i class="fa-solid fa-arrow-right"></i></button></div>
        <div class="quick-card"><h3><i class="fa-solid fa-bolt"></i> Quick Actions</h3><button @click="router.push('/add-property')"><i class="fa-solid fa-plus"></i> Add New Property</button><button @click="showToast('Analytics report opened')"><i class="fa-solid fa-chart-column"></i> View Analytics</button><button @click="showToast('Support team is ready')"><i class="fa-solid fa-headset"></i> Get Help</button></div>
      </aside>

      <main class="dashboard">
        <section class="dashboard-hero"><div><h1>My Properties</h1><p>Manage the properties you have listed on VibeLocate AI.</p></div><button @click="router.push('/add-property')"><i class="fa-solid fa-plus"></i> Add New Property</button></section>

        <section class="stats-row">
          <div v-for="stat in stats" :key="stat.label" class="stat"><i :class="stat.icon" :style="{ color: stat.color }"></i><div><span>{{ stat.label }}</span><b>{{ stat.value }}</b><small :style="{ color: stat.color }">{{ stat.note }}</small></div></div>
        </section>

        <section class="toolbar">
          <div class="status-tabs"><button v-for="tab in statusTabs" :key="tab.value" :class="{ active: selectedStatus === tab.value }" @click="selectedStatus = tab.value"><i :style="{ background: tab.color }"></i>{{ tab.label }} <b>{{ statusCount(tab.value) }}</b></button></div>
          <div class="search-tools"><label><i class="fa-solid fa-magnifying-glass"></i><input v-model="search" placeholder="Search your properties..."></label><button @click="filtersOpen = !filtersOpen"><i class="fa-solid fa-sliders"></i> Filter</button><select v-model="sortBy"><option value="newest">Newest</option><option value="price-desc">Price: High</option><option value="price-asc">Price: Low</option><option value="views">Most viewed</option></select></div>
        </section>
        <div v-if="filtersOpen" class="filter-panel"><label>Property type <select v-model="typeFilter"><option value="all">All types</option><option>Villa</option><option>Apartment</option><option>Penthouse</option></select></label><button @click="typeFilter = 'all'; search = ''">Reset filters</button></div>

        <div class="dashboard-grid">
          <section class="properties-grid">
            <article v-for="item in filteredProperties" :key="item.id" class="property-card">
              <div class="card-photo"><img :src="item.image" :alt="item.title"><span class="status" :class="item.status"><i></i>{{ labelStatus(item.status) }}</span><span v-if="item.featured" class="featured"><i class="fa-solid fa-crown"></i> Featured</span><button class="heart" @click="toggleSaved(item)"><i :class="item.saved ? 'fa-solid fa-heart' : 'fa-regular fa-heart'"></i></button></div>
              <div class="card-body"><h2>{{ item.title }}</h2><p><i class="fa-solid fa-location-dot"></i> {{ item.location }}</p><strong>{{ formatPrice(item.price) }}</strong><div class="property-specs"><span><i class="fa-solid fa-bed"></i>{{ item.beds }} Beds</span><span><i class="fa-solid fa-bath"></i>{{ item.baths }} Baths</span><span><i class="fa-solid fa-expand"></i>{{ item.size }} sqft</span></div><div class="metrics"><span><i class="fa-regular fa-eye"></i><b>{{ item.views.toLocaleString() }}</b><small>Views</small></span><span><i class="fa-solid fa-heart"></i><b>{{ item.saves }}</b><small>Saves</small></span><span><i class="fa-regular fa-user"></i><b>{{ item.leads }}</b><small>Inquiries</small></span><span><i class="fa-solid fa-wand-magic-sparkles"></i><b>{{ item.match }}%</b><small>AI Match</small></span></div><div class="card-actions"><button class="view" @click="viewProperty(item)">View Details <i class="fa-solid fa-arrow-right"></i></button><button @click="editProperty(item)">Edit</button><button class="more" @click="showToast(`More actions for ${item.title}`)"><i class="fa-solid fa-ellipsis"></i></button></div></div>
            </article>
            <div v-if="!filteredProperties.length" class="empty"><i class="fa-regular fa-building"></i><h2>No properties found</h2><p>Try changing the search or filters.</p></div>
