          <aside ref="inquiriesSection" class="right-column">
            <section class="inquiries"><div class="panel-head"><h3><i class="fa-regular fa-clipboard"></i> Recent Inquiries</h3><button @click="showToast('All inquiries opened')">View All <i class="fa-solid fa-arrow-right"></i></button></div><div v-for="lead in inquiries" :key="lead.name" class="lead"><span :style="{ background: lead.color }">{{ lead.initials }}</span><div><b>{{ lead.name }}</b><small>{{ lead.message }}</small></div><time>{{ lead.time }}</time></div></section>
            <section class="performance"><div class="panel-head"><h3><i class="fa-solid fa-chart-line"></i> Performance</h3></div><div class="chart"><i v-for="height in chartBars" :key="height" :style="{ height: `${height}%` }"></i></div><p><b>+35%</b> views compared with last month</p></section>
