  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import propertyService from '../services/propertyService'
import authService from '../services/authService'

defineProps({ embedded: { type: Boolean, default: false } })

const router = useRouter()
const readCurrentUser = () => {
  const stored = localStorage.getItem('auth_user') || sessionStorage.getItem('auth_user') || localStorage.getItem('user')
  let profile = {}
  try { profile = stored ? JSON.parse(stored) : {} } catch {}
  profile = profile?.data?.user || profile?.data || profile?.user || profile || {}
  return {
    name: profile.name || profile.full_name || [profile.first_name, profile.last_name].filter(Boolean).join(' ') || localStorage.getItem('vibe_user_name') || 'Anas User',
    email: profile.email || localStorage.getItem('vibe_user_email') || 'anas.user@example.com',
    avatar: profile.avatar || profile.profile_photo_url || profile.picture || profile.photo || profile.image || localStorage.getItem('vibe_user_avatar') || ''
  }
}
const currentUser = ref(readCurrentUser())
const initials = computed(() => currentUser.value.name.split(' ').slice(0, 2).map(n => n[0]).join('').toUpperCase())
const selectedStatus = ref('all'), search = ref(''), sortBy = ref('newest'), typeFilter = ref('all'), filtersOpen = ref(false), toastMessage = ref(''), inquiriesSection = ref(null)
const fallback = [
  { id: 1,title:'The Royal Atlantis Sky Villa',location:'Palm Jumeirah, Dubai',price:25000000,beds:5,baths:6,size:'7,200',status:'active',featured:true,image:'/images/photo-1600596542815-ffad4c1539a9.jfif',views:2450,saves:320,leads:28,match:95 },
  { id: 2,title:'Marina Shores Residence',location:'Dubai Marina, Dubai',price:4800000,beds:3,baths:4,size:'1,650',status:'active',image:'/images/photo-1512917774080-9991f1c4c750.jfif',views:1892,saves:214,leads:18,match:92 },
  { id: 3,title:'Jumeirah Bay Villa',location:'Jumeirah, Dubai',price:12500000,beds:3,baths:5,size:'5,200',status:'pending',image:'/images/photo-1600585154340-be6161a56a0c.avif',views:856,saves:96,leads:12,match:88 },
  { id: 4,title:'Emaar Beachfront Apartment',location:'Emaar Beachfront, Dubai',price:3200000,beds:2,baths:3,size:'1,400',status:'rented',image:'/images/photo-1545324418-cc1a3fa10c00.avif',views:1320,saves:165,leads:14,match:91 },
  { id: 5,title:'Arabian Ranches Family Villa',location:'Arabian Ranches, Dubai',price:6800000,beds:4,baths:5,size:'4,100',status:'draft',image:'/images/photo-1613977257363-707ba9348227.jfif',views:420,saves:48,leads:6,match:76 },
  { id: 6,title:'Downtown Views Apartment',location:'Downtown Dubai',price:5900000,beds:3,baths:4,size:'1,980',status:'active',image:'/images/photo-1600210492486-724fe5c67fb0.jfif',views:3240,saves:412,leads:33,match:94 },
  { id: 7,title:'Dubai Hills Estate Villa',location:'Dubai Hills Estate, Dubai',price:9750000,beds:5,baths:6,size:'4,800',status:'sold',image:'/images/photo-1512917774080-9991f1c4c750 (1).jfif',views:1980,saves:230,leads:21,match:89 }
]
const properties = ref(fallback)
const statusTabs = [{value:'all',label:'All Properties',color:'#1684ff'},{value:'active',label:'Active',color:'#21dfa5'},{value:'draft',label:'Draft',color:'#7d9ab2'},{value:'pending',label:'Pending',color:'#ffbf31'},{value:'sold',label:'Sold',color:'#9369ee'},{value:'rented',label:'Rented',color:'#1588ff'}]
const inquiries = [{name:'Sarah Johnson',initials:'SJ',message:'Enquired about Marina Shores Residence',time:'2 min ago',color:'#7368bd'},{name:'Mohammed Al Qassimi',initials:'MA',message:'Enquired about Downtown Views',time:'1 hour ago',color:'#3186a2'},{name:'Emma Wilson',initials:'EW',message:'Enquired about Jumeirah Bay Villa',time:'3 hours ago',color:'#c0953a'},{name:'Ravi Kumar',initials:'RK',message:'Enquired about Arabian Ranches Villa',time:'5 hours ago',color:'#258aa8'},{name:'Lina Hassan',initials:'LH',message:'Enquired about Emaar Beachfront',time:'1 day ago',color:'#7658bd'}]
const chartBars = [32,48,41,62,55,75,67,85,72,92,82,100]
const statusCount = status => status === 'all' ? properties.value.length : properties.value.filter(p => p.status === status).length
const stats = computed(() => [{label:'Total Listings',value:properties.value.length,note:'+20% from last month',icon:'fa-solid fa-house',color:'#168cff'},{label:'Active Listings',value:statusCount('active'),note:'Live on platform',icon:'fa-solid fa-circle',color:'#20e3a1'},{label:'Pending Approval',value:statusCount('pending'),note:'Awaiting review',icon:'fa-regular fa-clock',color:'#ffc23d'},{label:'Sold / Rented',value:statusCount('sold')+statusCount('rented'),note:'Completed listings',icon:'fa-solid fa-circle-check',color:'#20e3a1'},{label:'Total Views',value:properties.value.reduce((a,p)=>a+p.views,0).toLocaleString(),note:'+35% from last month',icon:'fa-regular fa-eye',color:'#00dcff'},{label:'New Leads',value:properties.value.reduce((a,p)=>a+p.leads,0),note:'+60% from last month',icon:'fa-solid fa-user-group',color:'#168cff'}])
const filteredProperties = computed(() => { let list=properties.value.filter(p => (selectedStatus.value==='all'||p.status===selectedStatus.value) && (typeFilter.value==='all'||p.title.toLowerCase().includes(typeFilter.value.toLowerCase())) && `${p.title} ${p.location}`.toLowerCase().includes(search.value.toLowerCase())); return [...list].sort((a,b)=>sortBy.value==='price-desc'?b.price-a.price:sortBy.value==='price-asc'?a.price-b.price:sortBy.value==='views'?b.views-a.views:b.id-a.id) })
const labelStatus = status => ({active:'Active',draft:'Draft',pending:'Pending',sold:'Sold',rented:'Rented'}[status] || status)
const formatPrice = price => `AED ${Number(price).toLocaleString()}`
const showToast = message => { toastMessage.value=message; setTimeout(()=>toastMessage.value='',2600) }
const viewProperty = item => { sessionStorage.setItem('vibelocate:selected-property',JSON.stringify(item)); router.push(`/property/${item.id}`) }
const editProperty = item => { localStorage.setItem('vibelocate:edit-property',JSON.stringify(item)); router.push({path:'/add-property',query:{edit:item.id}}) }
const toggleSaved = item => { item.saved=!item.saved; showToast(item.saved?'Property saved':'Property removed from saved') }
const scrollToInquiries = () => inquiriesSection.value?.scrollIntoView({behavior:'smooth'})
const logout = async () => { await authService.logout(); router.push('/login') }
onMounted(async()=>{ try{ const response=await propertyService.getProperties({per_page:50}); if(response.data?.length){ properties.value=response.data.map((p,i)=>({...p,status:['active','active','pending','rented','draft','active','sold'][i%7],featured:i===0,views:420+(i*613)%3000,saves:48+(i*67)%390,leads:6+(i*7)%34,match:p.aiMatch||88,size:p.size||p.area_sqft||'1,800'})) } }catch(error){ console.warn('Using owner dashboard fallback listings.',error) } })
</script>

